/* 只在第一次看到 ULP_EVENT 时 dump 关键寄存器，方便定位“到底是哪份配置触发了事件” */
static void bgt60_dump_regs_on_ulp_event_once(struct inf_bgt60_t *inf_bgt60, uint32_t ir_stat)
{
    static bool dumped;

    if (dumped || !inf_bgt60)
        return;
    dumped = true;

    //pr_info("[inf_bgt60] ===== ULP_EVENT DUMP (once) =====\n");
    //pr_info("[inf_bgt60] IR_STAT=0x%08X\n", ir_stat);

    /* IRQ / routing */
    DUMP_REG(BGT60CUTR13B_REG_IR_CTRL, "IR_CTRL");
    DUMP_REG(BGT60CUTR13B_REG_IR0_EN, "IR0_EN");
    DUMP_REG(BGT60CUTR13B_REG_IR1_EN, "IR1_EN");
    DUMP_REG(BGT60CUTR13B_REG_IR_CLEAR, "IR_CLEAR");

    /* Sequencer status */
    DUMP_REG(BGT60CUTR13B_REG_SEQ_GLOB_STAT, "SEQ_GLOB_STAT");
    DUMP_REG(BGT60CUTR13B_REG_SEQ1_STAT, "SEQ1_STAT");
    DUMP_REG(BGT60CUTR13B_REG_SEQ2_STAT, "SEQ2_STAT");

    /* Power/clock */
    DUMP_REG(BGT60CUTR13B_REG_PDC_CTRL, "PDC_CTRL");
    DUMP_REG(BGT60CUTR13B_REG_PDC_STAT, "PDC_STAT");
    DUMP_REG(BGT60CUTR13B_REG_PLL_STAT, "PLL_STAT");
    DUMP_REG(BGT60CUTR13B_REG_CLK_WUC, "CLK_WUC");
    DUMP_REG(BGT60CUTR13B_REG_CLK_STAT, "CLK_STAT");

    /* MD ULP core config/status */
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_CTRL, "MD_ULP_CTRL");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_ALG_CTRL, "MD_ULP_ALG_CTRL");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_RFFT_EXCL0, "MD_ULP_RFFT_EXCL0");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_RFFT_EXCL1, "MD_ULP_RFFT_EXCL1");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_CFAR_CTRL0, "MD_ULP_CFAR_CTRL0");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_CFAR_CTRL1, "MD_ULP_CFAR_CTRL1");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_CFAR_SCALE_L, "MD_ULP_CFAR_SCALE_L");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_CFAR_SCALE_H, "MD_ULP_CFAR_SCALE_H");
    DUMP_REG(BGT60CUTR13B_REG_MD_ULP_STAT, "MD_ULP_STAT");

//pr_info("[inf_bgt60] ===== ULP_EVENT DUMP END =====\n");
}

